        auto q_indexers = quant_vector_indexers_[field->name()];
        for (auto q_indexer : q_indexers) {
          auto s = q_indexer->Destroy();
          CHECK_RETURN_STATUS(s);
        }
        quant_vector_indexers_[field->name()] = {q_iter->second};
      }
    }
  }

  return Status::OK();
}

