  vector_column_params::ReadOptions options{options_.enable_mmap_, true};

  auto s = vector_indexer->Open(options);
  CHECK_RETURN_STATUS_EXPECTED(s);
  std::vector<VectorColumnIndexer::Ptr> to_merge_indexers =
