    std::unordered_map<std::string, VectorColumnIndexer::Ptr> *vector_indexers,
    std::unordered_map<std::string, VectorColumnIndexer::Ptr>
        *quant_vector_indexers) {
  auto field = collection_schema_->get_vector_field(column);
