                                                 *field_with_flat, concurrency);
      if (!vector_indexer.has_value()) {
        return vector_indexer.error();
      }

      vector_indexers->insert({column, vector_indexer.value()});

      new_segment_meta->remove_vector_persisted_block(column, false);
