  segments_map_[segment->id()] = segment;
  return Status::OK();
}

Status SegmentManager::remove_segment(SegmentID segment_id) {
  auto iter = segments_map_.find(segment_id);
  if (iter == segments_map_.end()) {
    return Status::NotFound("Segment not found");
