    return Status::InvalidArgument("Failed to convert filter");
  }
  if (0 !=
      index->Merge(engine_indexers, *engine_filter,
                   {merge_options.write_concurrency, merge_options.pool})) {
    return Status::InternalError("Failed to merge index");
  }
  return Status::OK();
}

